"""Shared helpers: config, HTTP, event log, webhook push, quiet hours."""
import json,os,re,sys,time,fcntl,urllib.request
from datetime import datetime
from zoneinfo import ZoneInfo
D=os.path.dirname(os.path.abspath(__file__)); EV=f"{D}/events.jsonl"
if os.path.exists(f"{D}/.env"):  # optional KEY=VALUE file for SPORTS_WEBHOOK_URL / SPORTS_WEBHOOK_KEY
    for l in open(f"{D}/.env"):
        k,_,v=l.strip().partition("=")
        if k and not k.startswith("#"): os.environ.setdefault(k,v.strip('"'))
def cfg(): return json.load(open(f"{D}/config.json"))
def tz(): return ZoneInfo(cfg().get("tz","UTC"))
def now(): return datetime.now(tz())
def get(url,t=15):
    return json.load(urllib.request.urlopen(urllib.request.Request(url,headers={"User-Agent":"Mozilla/5.0"}),timeout=t))
def quiet(dt=None):
    q=cfg().get("quiet_hours")  # e.g. ["23:30","07:30"] local, or null
    if not q: return False
    m=lambda s:int(s[:2])*60+int(s[3:]); dt=dt or now(); x=dt.hour*60+dt.minute; a,b=m(q[0]),m(q[1])
    return a<=x<b if a<b else (x>=a or x<b)
def match(f,ev):
    """Does follow f (team = id/abbrev/name, or game = event id, or neither = whole league) cover ESPN event ev?"""
    t=str(f.get("team") or "").lower(); g=str(f.get("game") or "")
    if g: return ev["id"]==g
    if not t: return True
    for c in ev["competitions"][0]["competitors"]:
        tm=c["team"]
        if any(t==str(tm.get(k,"")).lower() for k in ("id","abbreviation","displayName","shortDisplayName","name","location")) or re.search(r"\b"+re.escape(t)+r"\b",tm.get("displayName","").lower()): return True
def emit(kind,text,src="",key=None,**kw):
    """Append event + push. key: skip if an event with this key was already logged (dedupe across restarts)."""
    with open(EV,"a+") as f:
        fcntl.flock(f,fcntl.LOCK_EX); f.seek(0); ls=f.readlines(); n=len(ls)+1
        if key and any(json.loads(l).get("key")==key for l in ls): return
        if key: kw["key"]=key
        e={"id":n,"t":now().strftime("%a %H:%M"),"src":src,"kind":kind,"text":text,**kw}
        f.write(json.dumps(e)+"\n")
    print(time.strftime("%H:%M:%S"),"EVENT",kind,text,flush=True); push(e); return e
def push(e):
    if e["kind"]=="info": return
    if quiet() and e["kind"]!="test": print("quiet hours: holding",e["id"],flush=True); return
    url=os.environ.get("SPORTS_WEBHOOK_URL"); key=os.environ.get("SPORTS_WEBHOOK_KEY","").strip()
    if key.lower().startswith("bearer "): key=key[7:]
    if not url: print("PUSH FAILED: SPORTS_WEBHOOK_URL not set (backup routine will deliver)",flush=True); return
    h={"Content-Type":"application/json"}
    if key: h.update({"Authorization":"Bearer "+key,"X-Automation-Key":key})
    else: print("PUSH WARNING: SPORTS_WEBHOOK_KEY not set",flush=True)
    try:
        urllib.request.urlopen(urllib.request.Request(url,json.dumps({"source":"sports-alerts","events":[e]}).encode(),h,method="POST"),timeout=8).read()
        print("pushed",e["id"],flush=True)
    except Exception as x: print("PUSH FAILED:",getattr(x,"code",x),flush=True)
def status(src,state,**kw): json.dump({"state":state,"pid":os.getpid(),"updated":int(time.time()),**kw},open(f"{D}/status_{src}.json","w"))
if __name__=="__main__" and sys.argv[1:]==["test"]:
    emit("test","Test ping: sports alerts are wired up",src="test")
SA_EOF
```

