#!/usr/bin/env python3
"""ESPN live watcher: polls scoreboards of followed leagues, emits events, exits when no followed game is live/imminent."""
import json,os,sys,time
from datetime import datetime,timezone
from common import match,D,cfg,get,emit,status
API="https://site.api.espn.com/apis/site/v2/sports/"
REG={"soccer":2,"football":4,"basketball":4,"hockey":3,"baseball":9}
DEF={"basketball":["start","period","final"],"baseball":["start","score","final"]}
ALL=["start","score","red","period","final"]
SF=f"{D}/state_espn.json"; conf=json.load(open(SF)) if os.path.exists(SF) else {}; cand={}
conf={k:v for k,v in conf.items() if time.time()-datetime.fromisoformat(v["start"].replace("Z","+00:00")).timestamp()<36*3600}
K=lambda g:(g["state"],g["name"],g["period"],g["home"][1],g["away"][1],g["reds"])
def snap(ev,sport):
    c=ev["competitions"][0]; st=c["status"] if "status" in c else ev["status"]; s={}
    for x in c["competitors"]: s[x["homeAway"]]=[x["team"].get("shortDisplayName") or x["team"]["displayName"],int(float(x.get("score") or 0)),x["team"]["id"]]
    det=c.get("details") or []
    return {"state":st["type"]["state"],"name":st["type"]["name"],"period":st.get("period",0),"detail":st["type"].get("shortDetail",""),
            "home":s["home"],"away":s["away"],"reds":sum(1 for d in det if d.get("redCard")),"goals":sum(1 for d in det if d.get("scoringPlay")),
            "start":ev["date"],"sport":sport}
def line(g):
    h,a=g["home"],g["away"]
    return f"{h[0]} {h[1]}-{a[1]} {a[0]}" if g["sport"]=="soccer" else f"{a[0]} {a[1]} @ {h[0]} {h[1]}"
def who(d): return ", ".join(p.get("shortName") or p.get("displayName","") for p in d.get("athletesInvolved") or [])
def play_text(path,gid,g):
    try:
        s=get(f"{API}{path}/summary?event={gid}"); pl=s.get("scoringPlays") or [p for p in s.get("plays") or [] if p.get("scoringPlay")]
        m=[p for p in pl if p.get("homeScore")==g["home"][1] and p.get("awayScore")==g["away"][1]] or pl
        return (m[-1].get("text") or "").strip() if m else ""
    except Exception: return ""
def diff(path,gid,o,n,ev,want):
    out=[]; L=line(n); sp=n["sport"]
    if o["state"]=="pre" and n["state"]=="in": out.append(("start",f"Underway: {L}"))
    if (n["home"][1],n["away"][1])!=(o["home"][1],o["away"][1]):
        if n["home"][1]<o["home"][1] or n["away"][1]<o["away"][1]: out.append(("score",f"Score corrected: {L}"))
        else:
            side="home" if n["home"][1]>o["home"][1] else "away"
            if sp=="soccer":
                det=[d for d in ev["competitions"][0].get("details") or [] if d.get("scoringPlay") and d.get("team",{}).get("id")==n[side][2]]
                d=det[-1] if det and n["goals"]>=n["home"][1]+n["away"][1] else {}; og=" (OG)" if d.get("ownGoal") else ""; pen=" (pen)" if d.get("penaltyKick") else ""
                out.append(("score",f"GOAL {n[side][0]}! {L}"+(f" ({who(d)}{og}{pen} {d.get('clock',{}).get('displayValue','')})" if d else "")))
            else:
                tx=play_text(path,gid,n); lab={"hockey":"GOAL","baseball":"Run"}.get(sp,"Score")
                out.append(("score",f"{lab} {n[side][0]}: {L}"+(f" ({tx}, {n['detail']})" if tx else f" ({n['detail']})")))
    if n["reds"]>o.get("reds",0):
        r=[d for d in ev["competitions"][0].get("details") or [] if d.get("redCard")][-1]
        out.append(("red",f"RED CARD {n['home' if r.get('team',{}).get('id')==n['home'][2] else 'away'][0]}: {who(r)} {r.get('clock',{}).get('displayValue','')} | {L}"))
    if n["state"]=="in" and n["name"]!=o["name"]:
        if n["name"]=="STATUS_HALFTIME": out.append(("period",f"Half-time: {L}"))
        elif n["name"]=="STATUS_END_PERIOD": out.append(("period",f"{n['detail']}: {L}"))
    if n["state"]=="in" and o["state"]=="in" and n["period"]>REG.get(sp,99)>=o["period"]: out.append(("period",f"{'Extra time' if sp=='soccer' else 'Overtime'}: {L}"))
    if n["state"]=="post" and o["state"]!="post":
        out.append(("final",f"{'FINAL' if n['name']!='STATUS_POSTPONED' else 'POSTPONED'} ({n['detail']}): {L}"))
    for k,t in out:
        if k in want: emit(k,t,src="espn",game=gid,league=path,score=L)
def main():
    fol=[f for f in cfg()["follows"] if f.get("sport")!="f1"]
    if not fol: return
    t_end=time.time()+8*3600; first=True
    while time.time()<t_end:
        active=False; seen=0; now=datetime.now(timezone.utc)
        for path in sorted({f"{f['sport']}/{f['league']}" for f in fol}):
            try: evs=get(f"{API}{path}/scoreboard").get("events",[])
            except Exception as x: print("fetch error",path,x,flush=True); active=True; continue
            for ev in evs:
                fs=[f for f in fol if f"{f['sport']}/{f['league']}"==path and match(f,ev)]
                if not fs: continue
                sp=path.split("/")[0]; want=set(fs[0].get("events") or DEF.get(sp,ALL)); gid=ev["id"]; n=snap(ev,sp); seen+=1
                if gid not in conf:
                    conf[gid]=n
                    if n["state"]=="in": emit("start",f"Live alerts on: {line(n)} ({n['detail']})",src="espn",game=gid,league=path)
                elif K(n)==K(conf[gid]): conf[gid]=n; cand.pop(gid,None)
                else: diff(path,gid,conf[gid],n,ev,want); conf[gid]=n; cand.pop(gid,None)  # fire on first change (fast mode)
                c=conf[gid]; mins=(datetime.fromisoformat(c["start"].replace("Z","+00:00"))-now).total_seconds()/60
                if c["state"]=="in" or gid in cand or (c["state"]=="pre" and -90<mins<35): active=True
        json.dump(conf,open(SF,"w")); status("espn","running" if active else "done",followed_games=seen)
        if not active:
            if first: emit("info","No followed game live or starting within 35 min",src="espn")
            break
        first=False; time.sleep(10 if any(c["state"]=="in" for c in conf.values()) else 60)
    status("espn","done")
main()
SA_EOF
```

