#!/usr/bin/env python3
"""F1 live race watcher (F1 live timing SignalR Core). Emits lead/top-10/SC/VSC/red flag/retirement/result events."""
import asyncio, json, time, os, urllib.request, websockets, common
RS='\x1e'; TOPICS=["SessionInfo","DriverList","TrackStatus","RaceControlMessages","LapCount","TimingData","SessionStatus"]  # SessionStatus last so a finished race reports the real top 10
drivers={}; pos={}; retired=set(); leader=None; track=None; lap=None; seen_rc=0; session=None; started_evt=False; finished=False
pending={}; pend_t=0
def name(n): d=drivers.get(str(n),{}); return d.get("FullName") or d.get("BroadcastName") or d.get("Tla") or f"Car {n}"
F=next((f for f in common.cfg()["follows"] if f.get("sport")=="f1"),{}); WANT=set(F.get("events") or ["start","lead","positions","track","incident","retired","result"])
def emit(kind,text):
    if kind in WANT or kind=="info": common.emit(kind,text,src="f1",lap=lap,key=f"f1-{kind}-{session}" if kind in ("start","result") else None)
def status(s): common.status("f1",s,session=session)
def merge(a,b):
    for k,v in b.items():
        if isinstance(v,dict) and isinstance(a.get(k),dict): merge(a[k],v)
        else: a[k]=v
def top(n=10):
    r=sorted(((int(p),k) for k,p in pos.items() if str(p).isdigit()))[:n]
    return ", ".join(f"P{p} {name(k)}" for p,k in r)
TS={"2":"Yellow flag","4":"Safety Car deployed","5":"RED FLAG, race stopped","6":"Virtual Safety Car deployed","7":"VSC ending"}
def flush(force=False):
    global pend_t
    if not pending or (not force and time.time()-pend_t<4): return
    ups=[];downs=[]
    for k,(a,b) in sorted(pending.items(),key=lambda x:x[1][1]):
        if b<a and b!=1 and b<=10: ups.append(f"{name(k)} up to P{b} (from P{a})")
        elif b>a and b-a>=2 and a<=10: downs.append(f"{name(k)} drops to P{b} (from P{a})")
    pending.clear(); pend_t=0
    if ups or downs: emit("positions","; ".join(ups+downs))
def handle(topic,data,initial=False):
    global leader,track,lap,seen_rc,session,started_evt,finished
    if topic=="DriverList":
        for k,v in data.items():
            if isinstance(v,dict): drivers.setdefault(k,{}).update(v)
    elif topic=="SessionInfo": session=f"{data.get('Meeting',{}).get('Name','')} {data.get('Name','')}".strip() or session
    elif topic=="LapCount":
        lap=data.get("CurrentLap",lap)
    elif topic=="TrackStatus":
        s=str(data.get("Status"))
        if s!=track and not initial:
            if s in ("4","5","6"): emit("track",TS[s])
            elif s=="1" and track in ("4","5","6","7"): emit("track","Green flag, racing resumes")
        track=s
    elif topic=="RaceControlMessages":
        msgs=data.get("Messages",[])
        if isinstance(msgs,dict): msgs=[msgs[k] for k in sorted(msgs,key=int)]
        for m in msgs:
            if initial: seen_rc+=1; continue
            t=m.get("Message","").upper()
            if any(w in t for w in ("STOPPED","CRASH","COLLISION","SPUN","RETIRED","DEBRIS")) and "NOTED" not in t and "UNDER INVESTIGATION" not in t and "NO FURTHER" not in t:
                emit("incident",m.get("Message"))
    elif topic=="TimingData":
        for k,v in (data.get("Lines") or {}).items():
            if "Position" in v:
                old=pos.get(k)
                if not initial and old and str(old).isdigit() and str(v["Position"]).isdigit() and old!=v["Position"]:
                    if k not in pending: pending[k]=[int(old),int(v["Position"])]
                    else: pending[k][1]=int(v["Position"])
                    global pend_t
                    if not pend_t: pend_t=time.time()
                pos[k]=v["Position"]
            if v.get("Retired") and k not in retired:
                retired.add(k)
                if not initial: emit("retired",f"{name(k)} retires")
        cur=next((k for k,p in pos.items() if str(p)=="1"),None)
        if cur and cur!=leader:
            if leader and not initial: emit("lead",f"{name(cur)} takes the lead from {name(leader)}")
            leader=cur
    elif topic=="SessionStatus":
        s=data.get("Status")
        if s in ("Finished","Finalised","Ends") and not finished:
            flush(True); finished=True; emit("result",f"Chequered flag! {name(leader)} wins. Top 10: {top()}")
async def run():
    global started_evt
    req=urllib.request.Request("https://livetiming.formula1.com/signalrcore/negotiate?negotiateVersion=1",method="POST")
    with urllib.request.urlopen(req,timeout=20) as r:
        tok=json.load(r)["connectionToken"]; ck="; ".join(c.split(";")[0] for c in r.headers.get_all("Set-Cookie") or [])
    async with websockets.connect(f"wss://livetiming.formula1.com/signalrcore?id={tok}",max_size=None,additional_headers={"Cookie":ck},ping_interval=20) as ws:
        await ws.send(json.dumps({"protocol":"json","version":1})+RS)
        await ws.send(json.dumps({"type":1,"invocationId":"0","target":"Subscribe","arguments":[TOPICS]})+RS)
        while not finished:
            m=await asyncio.wait_for(ws.recv(),120)
            for part in m.split(RS):
                if not part: continue
                o=json.loads(part)
                if o.get("type")==3 and o.get("result"):
                    res=o["result"]
                    for t in TOPICS:
                        if t in res: handle(t,res[t],initial=True)
                    if (res.get("SessionInfo") or {}).get("Type")!="Race":
                        status("not_a_race"); emit("info","No live race session right now"); return "noraces"
                    st=(res.get("SessionStatus") or {}).get("Status")
                    if st in ("Finished","Finalised","Ends"): handle("SessionStatus",{"Status":st}); return
                    if not started_evt:
                        started_evt=True; status("running")
                        emit("start",f"Live alerts on for the {session}. Lap {lap or '?'}, {name(leader)} leads." if leader else f"Live alerts on for the {session}.")
                elif o.get("type")==1 and o.get("target")=="feed":
                    t,d=o["arguments"][0],o["arguments"][1]
                    handle(t,d); flush()
                    status("running")
from datetime import datetime,timezone,timedelta
def in_window():  # only connect from 35 min before to 3.5 h after a GP or Sprint start (jolpi.ca calendar)
    nw=datetime.now(timezone.utc)
    for r in common.get("https://api.jolpi.ca/ergast/f1/current/races.json")["MRData"]["RaceTable"]["Races"]:
        for x in (r,r.get("Sprint") or {}):
            if x.get("time") and -timedelta(minutes=35)<nw-datetime.fromisoformat(f"{x['date']}T{x['time'].replace('Z','')}+00:00")<timedelta(hours=3.5): return True
if not in_window(): status("no_race_window"); raise SystemExit
deadline=time.time()+4*3600
while not finished and time.time()<deadline:
    try:
        if asyncio.run(run())=="noraces": break
    except Exception as e:
        print("f1 reconnect:",e,flush=True); time.sleep(10)
status("done")
SA_EOF
```

