#!/usr/bin/env python3
"""List upcoming fixtures for config.json follows and the cron listeners for the game-day starter routine.
Usage: schedule.py [days=7] [--json]"""
import json,sys
from datetime import datetime,timedelta,timezone
from common import match,cfg,get,tz,quiet
API="https://site.api.espn.com/apis/site/v2/sports/"
DUR={"soccer":2.25,"football":3.75,"basketball":2.75,"hockey":3,"baseball":3.75,"f1":2.25}
def fixtures(days):
    Z=tz(); now=datetime.now(timezone.utc); end=now+timedelta(days=days); out={}
    for f in cfg()["follows"]:
        if f.get("sport")=="f1":
            for r in get("https://api.jolpi.ca/ergast/f1/current/races.json")["MRData"]["RaceTable"]["Races"]:
                for nm,x in (("Sprint",r.get("Sprint")),("Grand Prix",r)):
                    if x and x.get("time"):
                        t=datetime.fromisoformat(f"{x['date']}T{x['time'].replace('Z','')}+00:00")
                        if now-timedelta(hours=3)<t<end: out[f"f1-{r['round']}-{nm}"]=(t,"f1",f"{r['raceName']} {nm}" if nm=="Sprint" else r["raceName"])
            continue
        path=f"{f['sport']}/{f['league']}"
        for d in range(-1,days+1):
            ds=(now+timedelta(days=d)).strftime("%Y%m%d")
            try: evs=get(f"{API}{path}/scoreboard?dates={ds}&limit=300").get("events",[])
            except Exception as x: print("fetch error",path,ds,x,file=sys.stderr); continue
            for ev in evs:
                t=datetime.fromisoformat(ev["date"].replace("Z","+00:00"))
                if match(f,ev) and now-timedelta(hours=3)<t<end and ev["status"]["type"]["state"]!="post":
                    out[ev["id"]]=(t,f["sport"],f"{ev.get('name')} [{f['league']}]")
    return sorted(((t.astimezone(Z),sp,n,k) for k,(t,sp,n) in out.items()))
def crons(fx):
    st=[]; bk=[]; nw=datetime.now(tz())
    for t,sp,n,k in fx:  # starter 10 min before, then backup every 30 min for the expected duration
        x=(t-timedelta(minutes=10)).replace(second=0,microsecond=0); st.append(x)
        while (x:=x+timedelta(minutes=30))<=t+timedelta(hours=DUR.get(sp,3)): bk.append(x)
    kept=[]
    for x in sorted(st):
        if not kept or (x-kept[-1]).total_seconds()>=5*60: kept.append(x)
    for x in sorted(bk):
